CCoreState::CCoreState()
{
	m_name = zstrdup("CoreState");
	m_loading = false;
	m_loadstarted = false;
	zMathUnitMatrix(objMtx1);
	zMathUnitMatrix(objMtx2);
	m_skip_swap = 0;
}

